"use strict";

// The CALLEE-IDENTITY half of RWF-022, which needs no body analysis at all:
// calling an `async` function returns a Promise, and a Promise is not a
// constructor. RWF-020 correctly refuses to call this call abrupt -- it
// completes, and completes with a value -- so before RWF-022 nothing here
// fired either.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

// Returns a perfectly good class... wrapped in a Promise.
async function loadBase() {
  return class Base {};
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  class Mode extends loadBase() {}
  void Mode;
}

module.exports = safeOp;
